<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Cross-system identities</span><h2>External ID mappings</h2></div><span class="panel-meta"><?= count($mappings) ?> mapping(s)</span></header><div class="table-wrap"><table><thead><tr><th>Domain</th><th>Internal</th><th>External</th><th>Entity</th><th>Status</th></tr></thead><tbody><?php foreach($mappings as$m): ?><tr><td><?= h(status_label($m['domain_code'])) ?></td><td><?= h($m['internal_record_type'].' #'.$m['internal_record_id']) ?></td><td><?= h($m['external_record_type'].' · '.$m['external_record_id']) ?></td><td><?= h(entity_system_find($entities,(int)$m['entity_id'])['entity_name']??'Unknown') ?></td><td><?= badge($m['mapping_status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Governed mapping</span><h2>Stage external identity</h2></div></header><?php if(can('companies.administer')): ?><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_mapping"><input type="hidden" name="return_tab" value="mappings"><label><span>Connection</span><select name="connection_id"><?php foreach($connections as$c): ?><option value="<?= (int)$c['id'] ?>"><?= h($c['connection_name']) ?></option><?php endforeach; ?></select></label><label><span>Entity</span><select name="entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>Domain</span><input name="domain_code" value="suppliers"></label><label><span>Internal type</span><input name="internal_record_type" value="supplier"></label><label><span>Internal record ID</span><input type="number" name="internal_record_id" min="1" required></label><label><span>External type</span><input name="external_record_type" value="vendor"></label><label><span>External record ID</span><input name="external_record_id" required></label><label><span>External parent</span><input name="external_parent_id"></label><label><span>Effective</span><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required></textarea></label><div class="span-2"><button class="button primary">Stage Mapping</button></div></form><?php endif; ?></section></div>
